<?= $this->extend('layouts/main') ?><?= $this->section('content') ?>
<nav class="breadcrumbs" aria-label="Navegação estrutural"><a href="<?= site_url('comunidades') ?>">Comunidades</a><span>/</span><span><?= esc($project['name']) ?></span></nav>
<div class="page-head"><div><span class="badge"><?= esc($project['code']) ?></span><h1><?= esc($project['name']) ?></h1><p><?= esc($project['description'] ?: 'Sem descrição.') ?></p></div><div class="page-head-actions"><details class="action-menu"><summary aria-label="Ações de <?= esc($project['name']) ?>">Ações</summary><div class="action-menu-panel"><a href="<?= site_url('comunidades/'.$project['id'].'/colecoes/nova') ?>">Criar coleção</a><a href="<?= site_url('comunidades/'.$project['id'].'/editar') ?>">Editar dados</a><form method="post" action="<?= site_url('comunidades/'.$project['id'].'/visibilidade') ?>"><?= csrf_field() ?><label>Visibilidade<select name="visibility"><option value="public" <?= ($project['visibility'] ?? 'restricted') === 'public' ? 'selected' : '' ?>>Público</option><option value="restricted" <?= ($project['visibility'] ?? 'restricted') === 'restricted' ? 'selected' : '' ?>>Restrito</option><option value="excluded" <?= ($project['visibility'] ?? '') === 'excluded' ? 'selected' : '' ?>>Excluído</option></select></label><button type="submit">Aplicar</button></form><form method="post" action="<?= site_url('comunidades/'.$project['id'].'/excluir') ?>" onsubmit="return confirm('Excluir esta comunidade? O histórico será preservado.')"><?= csrf_field() ?><button class="danger-action" type="submit">Excluir</button></form></div></details></div></div>
<section aria-labelledby="collections-title"><div class="section-head"><h2 id="collections-title">Coleções</h2></div><div class="card-grid"><?php foreach ($collections as $collection): ?><?php $isSelected = $selectedCollectionId === $collection['id']; $description = trim((string) ($collection['description'] ?? '')); $descriptionSummary = mb_strlen($description) > 150 ? mb_substr($description, 0, 150) . '...' : $description; ?><article class="card collection-card <?= $isSelected ? 'is-selected' : '' ?>"><div class="collection-card-head"><h3><?= esc($collection['name']) ?></h3><?= view('collections/card_actions', ['collection' => $collection, 'canManageCollections' => $canManageCollections]) ?></div><?php if (! empty($collection['cover_image'])): ?><img class="collection-cover" src="<?= site_url('colecoes/'.$collection['id'].'/imagem') . '?v=' . sha1((string) $collection['cover_image']) ?>" alt="Imagem representativa da coleção <?= esc($collection['name']) ?>" loading="lazy"><?php endif ?><div><?php if ($descriptionSummary !== ''): ?><p class="collection-description"><?= esc($descriptionSummary) ?></p><?php endif ?></div><form method="post" action="<?= site_url('colecoes/'.$collection['id'].'/selecionar') ?>" class="community-select-form"><?= csrf_field() ?><button class="button <?= $isSelected ? 'selected-community' : 'secondary' ?>" type="submit" aria-pressed="<?= $isSelected ? 'true' : 'false' ?>"><?= $isSelected ? 'Coleção selecionada' : 'Selecionar Coleção' ?></button></form></article><?php endforeach ?></div><?php if (! $collections): ?><p class="empty">Nenhuma coleção cadastrada.</p><?php endif ?></section>
